// AI: below section was generated by an AI
// Static-IP safety net: if a static IP is configured but, for N seconds after
// boot (or after the static address was applied), there is no link or the
// gateway does not answer ARP, the node reverts to DHCP so it can be found
// again (and announces itself). Pure decision logic, host-tested by
// tools/loomx-node-test.js.

#include <stdint.h>

namespace loomx {

enum class FallbackDecision : uint8_t {
  Idle,     // nothing to do: DHCP, disabled, or already decided
  Waiting,  // static IP, still inside the grace period
  Healthy,  // link up and gateway answered: keep the static IP
  FallBack  // grace period over without link/gateway: switch to DHCP
};

struct FallbackInputs {
  bool staticConfigured = false;
  bool decided = false;          // Healthy or FallBack already happened this boot
  uint32_t timeoutMs = 60000;    // 0 disables the fallback
  uint32_t nowMs = 0;
  uint32_t sinceMs = 0;          // boot, or when the static address was applied
  bool linkUp = false;
  bool gatewayReachable = false;
};

inline FallbackDecision decideDhcpFallback(const FallbackInputs &in) {
  if (!in.staticConfigured || in.decided || in.timeoutMs == 0) return FallbackDecision::Idle;
  if (in.linkUp && in.gatewayReachable) return FallbackDecision::Healthy;
  // Unsigned subtraction is rollover-safe for millis().
  if (static_cast<uint32_t>(in.nowMs - in.sinceMs) < in.timeoutMs) return FallbackDecision::Waiting;
  return FallbackDecision::FallBack;
}

// Accepted configuration range for the grace period (seconds; 0 = off).
inline uint16_t clampFallbackSeconds(int seconds) {
  if (seconds <= 0) return 0;
  if (seconds < 10) return 10;
  if (seconds > 3600) return 3600;
  return static_cast<uint16_t>(seconds);
}

} // namespace loomx
